["desk_empty_gen",{referenced_image_paths:["C:\\Users\\kawau\\.codex\\generated_images\\01a0e252-b185-7ae0-ad60-5d3b95cedb97\\exec-2730d26e-532d-4992-b456-f8ceaacf2c95.png"],prompt:"Use case: precise-object-edit. Remove ONLY the stack of cream ticket paper at upper left and the entire steel ticket plier at lower right from this wood tabletop. Restore continuous natural wooden surface in those two areas. Keep every other thing pixel aligned: camera, desk wood grain, lamp, drawer, pull, lighting, shadows. This is the desk before the player brings their own paper and plier. Same dimensions, real photograph, no new objects.",transparent_background:false}],
["waiting_gen",{referenced_image_paths:["C:\\Users\\kawau\\.codex\\generated_images\\01a0e252-b185-7ae0-ad60-5d3b95cedb97\\exec-f6fc244d-748f-4940-931d-e4861cfc914f.png"],prompt:"Use case: photorealistic-natural. Reference: SAME small station waiting room seen through open wood doorway at right of platform photograph. New camera now INSIDE this waiting room, standing at platform door and facing ticket counter on opposite wall. Single landscape16:9 realistic photograph. Modest room 6x5m, old warm grey plaster and dark brown wood wainscot, wet footprints on worn floor, warm practical incandescent bulb. Left wall x8% has an open exterior exit to dark station forecourt, seen at angle. Low worn wooden passenger bench along left wall. Main ticket window in far wall at x55% y35%, authentic large glass opening covered by a simple sliding steel grille. Behind its bars, inside the office, a yellowed station floor plan is pinned visibly; don't try to print exact text or diagrams. Below the window at x55% y66% a small wooden drawer with a dark horizontal lock face. At x84% y38% closed narrow wooden door into station office, small frosted glass upper panel and old brass keyhole, no text on glass. RIGHT FOREGROUND x65% to85% y70% one coherent wooden ticket-inspection counter with an old warm brass desk lamp like an early20th-century station, tabletop empty, no paper, no pliers, no tools. LEFT of ticket window a small double timetable board with two aged sheets and a date holder, details not legible at this distance. No modern screens, no people, no surreal geometry, no extra locked safes, no game UI, no collage. Furniture natural lived-in functional arrangement, not an exhibition of puzzles. Cinematic quiet atmosphere through real light and rain, but all important objects visible.",transparent_background:false}]
];
const pending=jobs.map(async([key,args])=>{const r=await tools.image_gen__imagegen(args);store(key,r);text({key,hint:r.output_hint})});await yield_control();await Promise.all(pending);

